fn to_toggle_case(str1: &Vec<char>) -> Vec<char> {
    // Requires that str1 is a valid reference to a vector of characters
    // Ensures that the returned vector has the same length as str1
    // and that each character is toggled in case if it is an ASCII letter.
    // The function does not modify the original vector.
    // 
    // Requires: 
    // - str1 is a valid reference to a Vec<char>
    // 
    // Ensures:
    // - result.len() == str1.len()
    // - for all i in 0..str1.len(), result[i] == toggle_case(str1[i])
    // - where toggle_case(c) is defined as:
    //     - if c.is_ascii_lowercase() then c.to_ascii_uppercase()
    //     - if c.is_ascii_uppercase() then c.to_ascii_lowercase()
    //     - else c
    // 
    // Invariant:
    // - The function maintains the property that the output vector contains
    //   characters that are either the same as the input or toggled in case.
    // 
    // Decreases:
    // - The length of the input vector str1, which is non-negative.

    let result: Vec<char> = str1.iter().map(|&c| {
        if c.is_ascii_lowercase() {
            c.to_ascii_uppercase()
        } else if c.is_ascii_uppercase() {
            c.to_ascii_lowercase()
        } else {
            c
        }
    }).collect();

    result
}